.interactive-session .interactive-input-part > .chat-plan-review-widget-container,
.interactive-session .interactive-input-part .interactive-input-and-edit-session > .chat-plan-review-widget-container {
	width: 100%;
	position: relative;
	display: flex;
	flex-direction: column;
	gap: 8px;
}

/* When the part is docked inside the input container, drop our own
 * margin-bottom so it sits flush against the input. */
.interactive-session .interactive-input-part .chat-plan-review-container > .chat-confirmation-widget2.chat-plan-review {
	margin-bottom: 0;
}

/* Root container uses .chat-confirmation-widget2 styles for title / buttons,
 * plus our own layout and box overrides for the plan review widget. */
.interactive-session .chat-plan-review-container {
	display: flex;
	flex-direction: column;
}

.interactive-session .chat-plan-review-container > .chat-confirmation-widget2.chat-plan-review {
	max-height: min(420px, 50vh);
	min-height: 0;
	margin-bottom: 8px;
}

.interactive-session .chat-plan-review-container:focus {
	outline: none;
}

.interactive-session .chat-plan-review-container:focus-visible > .chat-confirmation-widget2.chat-plan-review,
.interactive-session .chat-plan-review-container:focus-within > .chat-confirmation-widget2.chat-plan-review {
	border-color: var(--vscode-focusBorder);
}

/* In the Agents window / editor the surface is the editor background. */
.agent-sessions-workbench .interactive-session .chat-plan-review-container > .chat-confirmation-widget2.chat-plan-review,
.editor-instance .interactive-session .chat-plan-review-container > .chat-confirmation-widget2.chat-plan-review {
	background-color: var(--vscode-editor-background);
}

/* ---------- Title bar ---------- */
.interactive-session .chat-plan-review-container .chat-plan-review-title {
	display: flex;
	align-items: center;
	gap: 8px;
	padding: 4px 6px 4px 12px;
	min-width: 0;
	flex-shrink: 0;
}

.interactive-session .chat-plan-review-container .chat-plan-review-title-content {
	flex: 1;
	min-width: 0;
	display: flex;
	align-items: center;
	gap: var(--vscode-spacing-size60);
	overflow: hidden;
}

.interactive-session .chat-plan-review-container .chat-plan-review-title-label {
	min-width: 0;
	font-weight: var(--vscode-fontWeight-semiBold);
	font-size: var(--vscode-chat-font-size-body-s);
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.interactive-session .chat-plan-review-container .chat-plan-review-outdated {
	flex-shrink: 0;
	padding: 0 var(--vscode-spacing-size60);
	border: var(--vscode-strokeThickness) solid var(--vscode-chat-requestBorder);
	border-radius: var(--vscode-cornerRadius-circle);
	color: var(--vscode-descriptionForeground);
	font-size: var(--vscode-fontSize-label3);
	font-weight: var(--vscode-fontWeight-regular);
	line-height: 14px;
}

.interactive-session .chat-plan-review-container .chat-plan-review-title-actions {
	display: flex;
	align-items: center;
	gap: 2px;
	flex-shrink: 0;
}

/* Icon-only square buttons (restore, chevron, edit): back to the default 22x22 square. */
.interactive-session .chat-plan-review-container .monaco-button.chat-plan-review-title-icon-button {
	width: 22px;
	padding: 0;
}

/* Inline slot in the title bar. The action buttons (Approve + Reject) get
 * re-rendered here when the widget is collapsed so the user can act on the
 * plan without expanding it. */
.interactive-session .chat-plan-review-container .chat-plan-review-inline-actions {
	display: none;
	align-items: center;
	gap: 6px;
	flex-shrink: 0;
	margin-left: auto;
	margin-right: 4px;
}

.interactive-session .chat-plan-review-container.chat-plan-review-collapsed .chat-plan-review-inline-actions {
	display: flex;
}

/* Action button row sizing — shared between the inline (collapsed) action
 * slot in the title bar and the footer. Keep these two rule sets together so
 * any tweaks stay in sync. */
.interactive-session .chat-plan-review-container .chat-plan-review-inline-actions .monaco-button,
.interactive-session .chat-plan-review-container .chat-plan-review-footer .monaco-button {
	width: auto;
	min-width: auto;
	padding: 0 10px;
	height: 22px;
}

.interactive-session .chat-plan-review-container .chat-plan-review-inline-actions .monaco-button-dropdown,
.interactive-session .chat-plan-review-container .chat-plan-review-footer .monaco-button-dropdown {
	width: auto;
	height: 22px;
	align-items: center;
}

.interactive-session .chat-plan-review-container .chat-plan-review-inline-actions .monaco-button-dropdown > .monaco-button,
.interactive-session .chat-plan-review-container .chat-plan-review-footer .monaco-button-dropdown > .monaco-button {
	height: 22px;
	box-sizing: border-box;
}

.interactive-session .chat-plan-review-container .chat-plan-review-inline-actions .monaco-button-dropdown > .monaco-button.monaco-dropdown-button,
.interactive-session .chat-plan-review-container .chat-plan-review-footer .monaco-button-dropdown > .monaco-button.monaco-dropdown-button {
	padding: 0 4px;
}

/* The default-colors separator has `padding: 4px 0` plus 1px top/bottom
 * borders; with content-box sizing it would visually overflow the 22px
 * dropdown wrapper and make the chevron half look taller than the primary
 * button. Force border-box and a fixed height so it matches. */
.interactive-session .chat-plan-review-container .chat-plan-review-inline-actions .monaco-button-dropdown > .monaco-button-dropdown-separator,
.interactive-session .chat-plan-review-container .chat-plan-review-footer .monaco-button-dropdown > .monaco-button-dropdown-separator {
	box-sizing: border-box;
	height: 22px;
	padding: 3px 0;
}

/* ---------- Scrollable markdown body ----------
 * Mirrors the flex + max-height chain used by
 * chatToolConfirmationCarouselPart so the DomScrollableElement has something
 * to clip and display its scrollbar against. DomScrollableElement sets the
 * inner element's `overflow: hidden` inline, so we don't set overflow here. */
.interactive-session .chat-plan-review-container .chat-confirmation-widget-message-scrollable.chat-plan-review-body-scrollable {
	flex: 1 1 auto;
	min-height: 0;
}

/* The inner element must fill the wrapper exactly — `DomScrollableElement`
 * measures `clientHeight` against it, so a taller layout height would break
 * scrollbar geometry once the feedback section claims part of the widget. */
.interactive-session .chat-plan-review-container .chat-confirmation-widget-message.chat-plan-review-body {
	padding: 6px 12px;
	background: transparent;
	border-bottom: none;
	height: 100%;
	box-sizing: border-box;
}

.interactive-session .chat-plan-review-container .chat-confirmation-widget-message.chat-plan-review-body .rendered-markdown p:first-child {
	margin-top: 0;
}

.interactive-session .chat-plan-review-container .chat-confirmation-widget-message.chat-plan-review-body .rendered-markdown > :last-child {
	margin-bottom: 0;
	margin-top: 0;
	padding-inline-start: 20px;
}

.interactive-session .chat-plan-review-container .rendered-markdown a {
	color: var(--vscode-textLink-foreground);
}

.interactive-session .chat-plan-review-container .rendered-markdown a:hover,
.interactive-session .chat-plan-review-container .rendered-markdown a:active {
	color: var(--vscode-textLink-activeForeground);
}

/* ---------- Feedback section (fixed; outside scroll) ---------- */
.interactive-session .chat-plan-review-container .chat-plan-review-feedback {
	display: flex;
	flex-direction: column;
	gap: 4px;
	padding: 6px 12px;
	border-top: 1px solid var(--vscode-chat-requestBorder);
	flex-shrink: 0;
}

.interactive-session .chat-plan-review-container .chat-plan-review-feedback-header {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 6px;
	min-width: 0;
}

.interactive-session .chat-plan-review-container .chat-plan-review-feedback-label {
	flex: 1;
	min-width: 0;
	font-size: var(--vscode-chat-font-size-body-s);
	color: var(--vscode-descriptionForeground);
}

/* Textarea styled the same as the question carousel freeform textarea. */
.interactive-session .chat-plan-review-container .chat-plan-review-feedback-textarea {
	width: 100%;
	min-height: 24px;
	max-height: 200px;
	padding: 3px 8px;
	border: 1px solid var(--vscode-input-border, var(--vscode-chat-requestBorder));
	background-color: var(--vscode-input-background);
	color: var(--vscode-input-foreground);
	border-radius: 4px;
	resize: none;
	font-family: var(--vscode-chat-font-family, inherit);
	font-size: var(--vscode-chat-font-size-body-s);
	box-sizing: border-box;
	overflow-y: hidden;
	align-content: center;
}

.interactive-session .chat-plan-review-container .chat-plan-review-feedback-textarea:focus {
	outline: 1px solid var(--vscode-focusBorder);
	border-color: var(--vscode-focusBorder);
}

.interactive-session .chat-plan-review-container .chat-plan-review-feedback-textarea::placeholder {
	color: var(--vscode-input-placeholderForeground);
}

/* ---------- Inline comments list (anchored feedback captured from editor) ---------- */
.interactive-session .chat-plan-review-container .chat-plan-review-comments-list-scrollable {
	margin-bottom: 2px;
}

.interactive-session .chat-plan-review-container .chat-plan-review-comments-list {
	display: flex;
	flex-direction: column;
	gap: 2px;
	max-height: 100px;
}

.interactive-session .chat-plan-review-container .chat-plan-review-comment-row {
	display: flex;
	align-items: stretch;
	min-width: 0;
	border: 1px solid transparent;
	border-radius: 4px;
}

.interactive-session .chat-plan-review-container .chat-plan-review-comment-row:hover {
	background: var(--vscode-list-hoverBackground);
}

.interactive-session .chat-plan-review-container .chat-plan-review-comment-row:focus-within {
	outline: 1px solid var(--vscode-focusBorder);
	outline-offset: -1px;
}

.interactive-session .chat-plan-review-container .chat-plan-review-comment-reveal {
	flex: 1;
	min-width: 0;
	display: flex;
	align-items: baseline;
	gap: 8px;
	padding: 3px 6px;
	background: transparent;
	border: none;
	color: var(--vscode-foreground);
	font: inherit;
	font-size: var(--vscode-chat-font-size-body-s);
	text-align: left;
	cursor: pointer;
}

.interactive-session .chat-plan-review-container .chat-plan-review-comment-reveal:focus {
	outline: none;
}

.interactive-session .chat-plan-review-container .chat-plan-review-comment-remove {
	flex-shrink: 0;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 22px;
	padding: 0;
	background: transparent;
	border: none;
	color: var(--vscode-icon-foreground);
	cursor: pointer;
	opacity: 0;
	transition: opacity 0.1s ease-in-out;
}

.interactive-session .chat-plan-review-container .chat-plan-review-comment-row:hover .chat-plan-review-comment-remove,
.interactive-session .chat-plan-review-container .chat-plan-review-comment-row:focus-within .chat-plan-review-comment-remove,
.interactive-session .chat-plan-review-container .chat-plan-review-comment-remove:focus {
	opacity: 1;
}

.interactive-session .chat-plan-review-container .chat-plan-review-comment-remove:hover {
	background: var(--vscode-toolbar-hoverBackground);
	border-radius: 4px;
}

.interactive-session .chat-plan-review-container .chat-plan-review-comment-line {
	flex-shrink: 0;
	color: var(--vscode-descriptionForeground);
	font-variant-numeric: tabular-nums;
}

.interactive-session .chat-plan-review-container .chat-plan-review-comment-text {
	flex: 1;
	min-width: 0;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

/* ---------- Feedback header actions (Back, Clear All) ---------- */
.interactive-session .chat-plan-review-container .chat-plan-review-feedback-header-actions {
	display: flex;
	align-items: center;
	gap: 4px;
	flex-shrink: 0;
}

.interactive-session .chat-plan-review-container .monaco-button.chat-plan-review-feedback-close,
.interactive-session .chat-plan-review-container .monaco-button.chat-plan-review-feedback-clear-all,
.interactive-session .chat-plan-review-container .monaco-button.chat-plan-review-review-button:not(.chat-plan-review-title-icon-button) {
	width: auto;
	min-width: auto;
	padding: 0 8px;
	height: 22px;
}

/* ---------- Footer buttons ---------- */
.interactive-session .chat-plan-review-container > .chat-confirmation-widget2.chat-plan-review > .chat-confirmation-widget-buttons.chat-plan-review-footer {
	justify-content: flex-start;
	border-top: 1px solid var(--vscode-chat-requestBorder);
	padding: 6px 8px;
	flex-shrink: 0;
}

.interactive-session .chat-plan-review-container > .chat-confirmation-widget2.chat-plan-review > .chat-confirmation-widget-buttons.chat-plan-review-footer .chat-buttons {
	display: flex;
	gap: 6px;
	align-items: center;
}

/* ---------- Collapsed state ---------- */
.interactive-session .chat-plan-review-container.chat-plan-review-collapsed > .chat-confirmation-widget2.chat-plan-review > .chat-confirmation-widget-message-scrollable,
.interactive-session .chat-plan-review-container.chat-plan-review-collapsed > .chat-confirmation-widget2.chat-plan-review > .chat-plan-review-feedback,
.interactive-session .chat-plan-review-container.chat-plan-review-collapsed > .chat-confirmation-widget2.chat-plan-review > .chat-confirmation-widget-buttons {
	display: none;
}

.interactive-session .chat-plan-review-container.chat-plan-review-collapsed > .chat-confirmation-widget2.chat-plan-review > .chat-plan-review-title {
	border-bottom: none;
}

/* ---------- Submitted / used state ---------- */
.interactive-session .chat-plan-review-container.chat-plan-review-used > .chat-confirmation-widget2.chat-plan-review > .chat-plan-review-feedback,
.interactive-session .chat-plan-review-container.chat-plan-review-used > .chat-confirmation-widget2.chat-plan-review > .chat-confirmation-widget-buttons {
	display: none;
}
