.chat-execute-toolbar.chat-voice-input-actions-multiple .monaco-action-bar .action-item > .action-label.codicon-mic-download-compact,
.chat-execute-toolbar.chat-voice-input-actions-multiple .monaco-action-bar .action-item > .action-label.codicon-voice-mode-compact,
.chat-execute-toolbar.chat-voice-input-actions-multiple .monaco-action-bar .action-item > .action-label.codicon-loading-compact,
.chat-execute-toolbar.chat-voice-input-actions-multiple .monaco-action-bar .action-item > .action-label.codicon-debug-disconnect-compact {
	border: var(--vscode-strokeThickness) solid var(--vscode-input-border, var(--vscode-editorWidget-border));
}

@keyframes chat-voice-icon-glow {
	0%,
	100% {
		box-shadow: 0 0 2px var(--chat-voice-icon-glow-color);
	}

	50% {
		box-shadow: 0 0 5px var(--chat-voice-icon-glow-color);
	}
}

/* Voice mode mic glyph: tinted with the same theme-derived accent as the ambient
	glow (published as `--voice-accent` by the glow controller). The glow keeps the
	button's resting shape — only its color and the pulse change between states, so
	the control never morphs from a circle into a rounded square mid-session. */
.chat-input-container.voice-active .chat-input-toolbars .action-label.codicon-voice-mode-compact {
	--chat-voice-icon-glow-color: color-mix(in srgb, var(--voice-accent, var(--vscode-charts-blue, #58a6ff)) 40%, transparent);
	color: var(--voice-accent, var(--vscode-charts-blue, #58a6ff)) !important;
	border-radius: var(--vscode-cornerRadius-circle);
}

.monaco-workbench.monaco-enable-motion .chat-input-container.voice-active.voice-listening .chat-input-toolbars .action-label.codicon-voice-mode-compact,
.monaco-workbench.monaco-enable-motion .chat-input-container.voice-active.voice-speaking .chat-input-toolbars .action-label.codicon-voice-mode-compact {
	animation: chat-voice-icon-glow 1.4s ease-in-out infinite;
}

/* Voice mode: green disconnect button. This has to out-specify the blanket
	`icon-foreground !important` rule that colors every toolbar codicon, so it
	carries the full toolbar path rather than a short `.chat-input-container`
	prefix — with equal `!important` the higher specificity wins, and the short
	form silently lost the cascade and rendered grey. */
.interactive-session .chat-input-toolbars > .chat-execute-toolbar .monaco-action-bar .action-item > .action-label.codicon-debug-disconnect-compact {
	color: var(--vscode-charts-green, #3fb950) !important;
}

/*
 * Voice mode connecting indicator: only spin the spinner glyph, not the whole
 * button. Otherwise the action-label (including its hover background) rotates
 * along with the icon.
 */
.chat-input-container .chat-input-toolbars .action-label.codicon-loading,
.chat-input-container .chat-input-toolbars .action-label.codicon-loading-compact {
	animation: none;
}

.chat-input-container .chat-input-toolbars .action-label.codicon-loading::before,
.chat-input-container .chat-input-toolbars .action-label.codicon-loading-compact::before {
	display: inline-block;
	transform-origin: center center;
	animation: codicon-spin 1.5s steps(30) infinite;
}

.monaco-reduce-motion .chat-input-container .chat-input-toolbars .action-label.codicon-loading::before,
.monaco-reduce-motion .chat-input-container .chat-input-toolbars .action-label.codicon-loading-compact::before {
	animation: none;
}

.monaco-reduce-motion .action-item.chat-restore-checkpoint-item.confirming .action-label:first-child {
	animation: none;
	background: none;
	-webkit-text-fill-color: currentColor;
	color: var(--vscode-foreground);
}

/* Dictation model download: while the on-device speech-to-text model downloads
	on first use, the toolbar shows a download icon wrapped by a circular
	progress ring (see DictationDownloadActionViewItem) instead of a spinning
	mic, so the wait reads as a determinate download rather than a hang. */
.monaco-action-bar .action-item.dictation-download-item {
	position: relative;
}

.monaco-action-bar .action-item.dictation-download-item > .dictation-download-ring {
	position: absolute;
	top: 50%;
	left: 50%;
	/* Sized to hug the compact 12px download glyph rather than the full button. */
	width: 16px;
	height: 16px;
	transform: translate(-50%, -50%) rotate(-90deg);
	pointer-events: none;
}

.monaco-action-bar .action-item.dictation-download-item > .dictation-download-ring .dictation-download-ring-track {
	fill: none;
	stroke: var(--vscode-progressBar-background);
	stroke-width: 1.5;
	opacity: 0.25;
}

/* In high-contrast themes progressBar.background is the solid contrastBorder;
	keep the track fully opaque so it stays visible against the arc. */
.hc-black .action-item.dictation-download-item > .dictation-download-ring .dictation-download-ring-track,
.hc-light .action-item.dictation-download-item > .dictation-download-ring .dictation-download-ring-track {
	opacity: 1;
}

.monaco-action-bar .action-item.dictation-download-item > .dictation-download-ring .dictation-download-ring-progress {
	fill: none;
	stroke: var(--vscode-progressBar-background);
	stroke-width: 1.5;
	stroke-linecap: round;
}

.monaco-workbench.monaco-enable-motion .action-item.dictation-download-item > .dictation-download-ring .dictation-download-ring-progress {
	transition: stroke-dashoffset 120ms ease;
}

/* Keep the progress arc moving while the model downloads or loads so the
	affordance reads as active even between percentage updates. Gated on
	enable-motion to respect reduced motion. */
.monaco-workbench.monaco-enable-motion .dictation-download-ring {
	animation: dictation-download-ring-spin 1.2s linear infinite;
}

.monaco-workbench.monaco-enable-motion .action-item.dictation-download-item > .dictation-download-ring.indeterminate .dictation-download-ring-progress {
	transition: none;
}

@keyframes dictation-download-ring-spin {
	from {
		transform: translate(-50%, -50%) rotate(-90deg);
	}
	to {
		transform: translate(-50%, -50%) rotate(270deg);
	}
}
