/* Shared workbench chat-pill presentation. */
.chat-pill-location-hover-panel .action-list-submenu-hover-header {
	width: min(420px, 70vw);
	max-width: 100%;
}

.chat-pill-location-hover {
	box-sizing: border-box;
	max-width: 100%;
	white-space: normal;
	overflow-wrap: anywhere;
}

.chat-pills,
.chat-pills .monaco-toolbar,
.chat-pills .monaco-action-bar,
.chat-pills .monaco-action-bar .actions-container {
	display: flex;
	align-items: center;
	min-width: 0;
}

.chat-pills.hidden {
	display: none;
}

/* Take hit-testing back from the click-through row the pills may float in. */
.chat-pills .monaco-action-bar .action-item {
	pointer-events: auto;
}

.chat-pills .monaco-action-bar .actions-container {
	gap: var(--vscode-spacing-size60);
}

.chat-pill-item {
	display: inline-flex;
	align-items: center;
	flex-shrink: 0;
}

.chat-pill-item .monaco-button.chat-pill-button {
	display: inline-flex;
	align-items: center;
	width: auto;
	gap: var(--vscode-spacing-size40);
	border-radius: var(--vscode-cornerRadius-medium);
	font-variant-numeric: tabular-nums;
	white-space: nowrap;
	touch-action: manipulation;
}

/* Tint the opaque base `chatPills.ts` sets, so a translucent pill color never
	shows the content behind the pill. */
.chat-pill-item .monaco-button.chat-pill-button.secondary {
	background-image: linear-gradient(var(--vscode-button-secondaryBackground), var(--vscode-button-secondaryBackground));
}

.chat-pill-item .monaco-button.chat-pill-button.secondary:hover,
.chat-pill-item .monaco-button.chat-pill-button.secondary:focus {
	background-image: linear-gradient(var(--vscode-button-secondaryHoverBackground), var(--vscode-button-secondaryHoverBackground));
}

/* Inset the focus ring so it sits on the pill's own border rather than the
	bloated ring the base `outline-offset: 2px` would draw. */
.chat-pill-item .monaco-button.chat-pill-button:focus {
	outline-offset: -1px !important;
}

/* Inset the focus ring so it sits on the pill's own border rather than the
	bloated ring the base `outline-offset: 2px` would draw. Applies to every pill
	in the row, including hosted ones. */
.chat-pills .monaco-button:focus {
	outline-offset: -1px !important;
}

.chat-pills .monaco-action-bar .chat-hosted-pill {
	display: inline-flex;
	align-items: center;
	min-width: 0;
}

.monaco-workbench .chat-pill-icon.codicon[class*=codicon-] {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: var(--vscode-codiconFontSize-compact);
	height: var(--vscode-codiconFontSize-compact);
	margin: 0;
	font-size: var(--vscode-codiconFontSize-compact);
	flex-shrink: 0;
}

/* Section-backed pills (artifacts, customizations, browsers, subagents) can
	carry a long entry label, so they cap their width and ellipsize rather than
	pushing their neighbours out of the row. */
.chat-pills .monaco-action-bar .chat-dropdown-pill,
.chat-pills .monaco-action-bar .chat-resource-pill {
	max-width: 280px;
}

.chat-pill-item .monaco-button.chat-dropdown-pill-button,
.chat-pill-item .monaco-button.chat-resource-pill-button {
	min-width: 0;
	max-width: 280px;
	overflow: hidden;
}

.chat-dropdown-pill-button .chat-pill-label {
	min-width: 0;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

/* The chevron shares the leading glyph's compact box. `chevron-down-compact` is
	drawn on that box's centre, so it needs no nudge to sit on the label. */
.monaco-workbench .chat-pill-chevron.codicon {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: var(--vscode-codiconFontSize-compact);
	height: var(--vscode-codiconFontSize-compact);
	margin: 0;
	font-size: var(--vscode-codiconFontSize-compact);
	flex-shrink: 0;
}

/* The themed file icon carries its own leading gap, so the pill adds barely any. */
.chat-pill-item .monaco-button.chat-resource-pill-button {
	padding-left: var(--vscode-spacing-size20);
}

.chat-pill-item .monaco-button.chat-resource-pill-button .chat-resource-pill-compact-icon {
	display: none;
}

.chat-resource-pill-button .monaco-icon-label {
	align-items: center;
	min-width: 0;
	overflow: hidden;
	font-size: var(--vscode-fontSize-body2);
}

.chat-resource-pill-button .monaco-icon-label::before {
	background-size: var(--vscode-codiconFontSize-compact);
	width: var(--vscode-codiconFontSize-compact);
	height: 14px;
}

/* File rows render a themed file icon in the same slot codicon rows use, so
	every label in the dropdown starts on the same vertical line. The icon paints
	through `::before`, which would otherwise sit on the row's text baseline and
	ride high, so the slot takes the row's height and centres the icon in it. */
.action-widget .monaco-list-row.action .icon.file-icon {
	display: flex;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;
	width: var(--vscode-codiconFontSize);
	height: var(--vscode-spacing-size240);
}

.action-widget .monaco-list-row.action .icon.file-icon::before {
	width: var(--vscode-codiconFontSize);
	background-size: var(--vscode-codiconFontSize);
	background-repeat: no-repeat;
	background-position: center center;
}

.action-widget.chat-pill-dropdown .monaco-list .monaco-list-row.has-toolbar:not(.has-standalone-toggle):not(.has-inline-toggle):not(.has-detail) {
	padding-right: 0;
}

.action-widget.chat-pill-dropdown .monaco-list .monaco-list-row.has-toolbar:not(.has-standalone-toggle):not(.has-inline-toggle):not(.has-detail) .action-list-item-toolbar {
	margin-right: 0;
}

.action-widget.chat-pill-dropdown .monaco-list-row.chat-pill-github-reference .action-item-badge {
	margin-left: var(--vscode-spacing-size40);
	padding: 0;
	border-radius: 0;
	background: transparent;
	color: var(--vscode-descriptionForeground);
	font-size: inherit;
	line-height: inherit;
}

.chat-pill-image-preview {
	display: flex;
	flex-direction: column;
	width: min(320px, calc(100vw - var(--vscode-spacing-size240)));
	color: var(--vscode-foreground);
}

.chat-pill-image-preview-unavailable {
	padding: var(--vscode-spacing-size80);
	overflow-wrap: anywhere;
}

.chat-pill-image-preview-unavailable {
	color: var(--vscode-descriptionForeground);
}

/* Horizontally scrollable status pills above a chat input. */
.chat-pills-row {
	width: 100%;
	min-width: 0;
}

.chat-pills-row-content {
	display: flex;
	align-items: center;
	justify-content: flex-start;
	gap: var(--vscode-spacing-size60);
	width: 100%;
	min-width: 0;
	box-sizing: border-box;
	padding: var(--vscode-spacing-size20) 0 var(--vscode-spacing-size40) 0;
}

.chat-pills-row-content > .chat-pills {
	flex-shrink: 0;
}

.chat-pills-row-content > * {
	pointer-events: auto;
}

.chat-pills-row.hidden {
	display: none;
}

.chat-pills-row.compact .chat-pills-row-content,
.chat-pills-row.compact .chat-pills .monaco-action-bar .actions-container {
	gap: var(--vscode-spacing-size40);
}

.chat-pills-row.compact .chat-pill-item .monaco-button.chat-pill-button {
	gap: var(--vscode-spacing-size20);
	padding-left: var(--vscode-spacing-size40);
	padding-right: var(--vscode-spacing-size40);
}

/* Compact rows are truly collapsed rather than merely tighter: all current
	pill renderers keep their identifying icon while labels, counters and dropdown
	chevrons remain available through the button's tooltip and accessible name. */
.chat-pills-row.compact .chat-pill-label,
.chat-pills-row.compact .changes-stats-files,
.chat-pills-row.compact .monaco-animated-counter,
.chat-pills-row.compact .chat-pill-chevron,
.chat-pills-row.compact .chat-resource-pill-button .monaco-icon-label {
	display: none;
}

.chat-pills-row.compact .chat-pill-item .monaco-button.chat-resource-pill-button .chat-resource-pill-compact-icon {
	display: inline-flex;
}

/* Keep the visibility menu reachable when every pill with data is hidden. */
.chat-pills-row.empty {
	pointer-events: auto;
}

.chat-pills-row.empty .chat-pills-row-content {
	min-height: var(--vscode-spacing-size120);
}

.chat-pills-row.empty .chat-pills-row-content:focus-visible {
	outline: var(--vscode-strokeThickness) solid var(--vscode-focusBorder);
	outline-offset: calc(-1 * var(--vscode-strokeThickness));
	border-radius: var(--vscode-cornerRadius-small);
}

/* The floating row is click-through, so its slider is informational only. */
.chat-pills-row > .scrollbar > .slider {
	background: transparent;
}

.chat-pills-row > .scrollbar.horizontal > .slider::before {
	content: '';
	position: absolute;
	inset: var(--vscode-strokeThickness);
	border-radius: var(--vscode-cornerRadius-circle);
	background: var(--vscode-scrollbarSlider-background);
}

.chat-pills-row > .scrollbar > .slider:hover::before {
	background: var(--vscode-scrollbarSlider-hoverBackground);
}

.chat-pills-row > .scrollbar > .slider.active::before {
	background: var(--vscode-scrollbarSlider-activeBackground);
}
